function preparar(x) {
  const p = x.interpretation || {};
  const batchIndex = Number.isInteger(Number(x.batch_index)) ? Number(x.batch_index) : null;
  const batchCount = Number.isInteger(Number(x.batch_count)) ? Number(x.batch_count) : null;
  const suffix = batchIndex===null ? '' : `-${batchIndex+1}`;
  const id = `${Date.now()}-${x.telegram_message_id || Math.floor(Math.random()*100000)}${suffix}`;

  if (p.intent === 'saldo_inversion') {
    return {
      target:'Inversiones',
      chat_id:x.chat_id,
      ack:`✅ Saldo ${p.inversion} registrado: $${Number(p.monto_ars).toLocaleString('es-AR')} al ${p.fecha}`,
      row:{
        "Periodo cierre": p.fecha,
        "Inversión": p.inversion,
        "Saldo cierre ARS": p.monto_ars,
        "Saldo inicio ARS": null,
        "Aportes ARS": null,
        "Rescates ARS": null,
        "Resultado financiero ARS": null,
        "Resultado %": null,
        "Fuente / nota": "Telegram"
      }
    };
  }

  const currency=String(p.moneda_original||'ARS').toUpperCase();
  const original=p.monto_original ?? p.monto_ars;
  const fx=Number(p.cotizacion_ars||0) || null;
  const arsProvided=(p.monto_ars===null||p.monto_ars===undefined||p.monto_ars==='') ? null : Number(p.monto_ars);
  // En gastos manuales USD, si la cotización ya es conocida materializamos el equivalente ARS.
  // Conservamos siempre moneda/monto original; sin cotización no inventamos un equivalente.
  const arsEq=(currency==='USD' && arsProvided===null && fx && Number.isFinite(Number(original)))
    ? Math.abs(Number(original))*fx
    : arsProvided;
  let amountLabel;
  if(currency==='USD'){
    amountLabel=`USD ${Number(original||0).toLocaleString('es-AR',{minimumFractionDigits:2,maximumFractionDigits:2})}`;
    if(arsEq!==null && Number.isFinite(arsEq)) amountLabel+=` → $${arsEq.toLocaleString('es-AR',{minimumFractionDigits:2,maximumFractionDigits:2})}`;
    if(fx) amountLabel+=` (cot. $${fx.toLocaleString('es-AR',{minimumFractionDigits:2,maximumFractionDigits:2})})`;
  } else {
    amountLabel=`$${Number(p.monto_ars||0).toLocaleString('es-AR',{minimumFractionDigits:2,maximumFractionDigits:2})}`;
  }

  return {
    target:'Movimientos',
    chat_id:x.chat_id,
    ack:`✅ Registrado${batchCount&&batchCount>1?` (${batchIndex+1}/${batchCount})`:''}: ${p.detalle || p.subtipo || p.clase} — ${amountLabel}`,
    row:{
      "ID": `M-${id}`,
      "Fecha": p.fecha,
      "Clase": p.clase,
      "Subtipo": p.subtipo,
      "Monto ARS": arsEq,
      "Moneda original": p.moneda_original || "ARS",
      "Monto original": p.monto_original ?? p.monto_ars,
      "Cuenta origen": p.cuenta_origen,
      "Cuenta destino": p.cuenta_destino,
      "Categoría": p.categoria,
      "Detalle": p.detalle || x.text,
      "Persona": x.persona,
      "Origen dato": "Telegram",
      "Lote importación": null,
      "Referencia": batchIndex===null
        ? `tg:${x.chat_id}:${x.telegram_message_id}`
        : `tg:${x.chat_id}:${x.telegram_message_id}:${batchIndex+1}`,
      "Confianza IA": p.confidence,
      "Estado revisión": "OK",
      "ID relacionado": null,
      "Cotización ARS": p.cotizacion_ars ?? null,
      "Fuente cotización": p.fuente_cotizacion ?? null
    }
  };
}

return items.map((item, idx) => ({
  json: preparar(item.json),
  binary: item.binary,
  pairedItem: {item: idx}
}));

const x=$('Decidir / guardar contexto').first().json;
const p=x.interpretation||{};

function safeRows(nodeName, predicate){
  try {
    return $(nodeName).all().map(i=>i.json).filter(predicate);
  } catch (e) {
    return [];
  }
}

const mov=safeRows('Leer movimientos consulta', r=>r.ID);
const acc=safeRows('Leer cuentas consulta', r=>r.Cuenta);
const cards=safeRows('Leer tarjetas consulta', r=>r['ID resumen']);
const inv=safeRows('Leer inversiones consulta', r=>r['Inversión']);
const pf=safeRows('Leer plazos fijos consulta', r=>r.ID);

const tz=x._cfg.timezone||'America/Argentina/Buenos_Aires';
function nowParts(){
  const ps=new Intl.DateTimeFormat('en-CA',{timeZone:tz,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());
  const g=k=>Number(ps.find(z=>z.type===k)?.value); return {y:g('year'),m:g('month'),d:g('day')};
}
function iso(y,m,d){return `${String(y).padStart(4,'0')}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`;}
function dateKey(v){
  if(v===null||v===undefined||v==='')return null;
  if(typeof v==='number'){const d=new Date(Date.UTC(1899,11,30)+Number(v)*86400000);return d.toISOString().slice(0,10);}
  const s=String(v);
  let m=s.match(/^(\d{4})-(\d{2})-(\d{2})/);if(m)return `${m[1]}-${m[2]}-${m[3]}`;
  m=s.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{2,4})/);
  if(m){let y=Number(m[3]);if(y<100)y+=2000;return iso(y,Number(m[2]),Number(m[1]));}
  const d=new Date(s);return isNaN(d)?null:d.toISOString().slice(0,10);
}
function num(v){
  if(v===null||v===undefined||v==='')return 0;
  if(typeof v==='number')return Number.isFinite(v)?v:0;
  let s=String(v).replace(/\$/g,'').replace(/\s/g,'').trim();
  if(!s)return 0;
  if(s.includes(',')&&s.includes('.')) s=s.lastIndexOf(',')>s.lastIndexOf('.')?s.replace(/\./g,'').replace(',','.'):s.replace(/,/g,'');
  else if(s.includes(',')) s=s.replace(/\./g,'').replace(',','.');
  const n=Number(s.replace(/[^\d.-]/g,'')); return Number.isFinite(n)?n:0;
}
function money(v){return '$'+Number(v||0).toLocaleString('es-AR',{minimumFractionDigits:2,maximumFractionDigits:2});}
function usd(v){return 'USD '+Number(v||0).toLocaleString('es-AR',{minimumFractionDigits:2,maximumFractionDigits:2});}
function addDays(s,n){const d=new Date(s+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10);}
function monthStart(y,m){return iso(y,m,1);}
function nextMonth(y,m){return m===12?iso(y+1,1,1):iso(y,m+1,1);}
function monthEnd(y,m){const d=new Date(Date.UTC(y,m,0));return d.toISOString().slice(0,10);}
function inRange(d,a,b){return d&&d>=a&&d<=b;}

const np=nowParts(),today=iso(np.y,np.m,np.d);
function rangeFor(period){
  if(period==='previous_month'){const d=new Date(Date.UTC(np.y,np.m-2,1));const y=d.getUTCFullYear(),m=d.getUTCMonth()+1;return [monthStart(y,m),monthEnd(y,m)];}
  if(period==='current_year')return [iso(np.y,1,1),iso(np.y,12,31)];
  if(period==='current_week'){
    const d=new Date(today+'T00:00:00Z'); const dow=(d.getUTCDay()+6)%7;
    return [addDays(today,-dow),addDays(today,6-dow)];
  }
  if(period==='next_days'){const n=Number(p.query_days||15);return [today,addDays(today,n)];}
  if(period==='until_month_end')return [today,monthEnd(np.y,np.m)];
  if(period==='specific_month'){
    const y=Number(p.query_year||np.y),m=Number(p.query_month||np.m);return [monthStart(y,m),monthEnd(y,m)];
  }
  if(period==='all')return ['1900-01-01','2999-12-31'];
  return [monthStart(np.y,np.m),monthEnd(np.y,np.m)];
}
const [from,to]=rangeFor(p.query_period||'current_month');
const activeMov=mov.filter(r=>String(r['Estado revisión']||'').toUpperCase()!=='ANULADO');
const periodMov=activeMov.filter(r=>inRange(dateKey(r.Fecha),from,to));

// --------------------------------------------------------------
// Valuación multimoneda para REPORTES (no altera Movimientos).
// Prioridad USD: Monto ARS/cotización explícita > operación real de compra USD > blue histórico API.
// --------------------------------------------------------------
function numOrNull(v){
  if(v===null||v===undefined||v==='') return null;
  if(typeof v==='number') return Number.isFinite(v)?v:null;
  let s=String(v).replace(/\$/g,'').replace(/\s/g,'').trim();
  if(!s) return null;
  if(s.includes(',')&&s.includes('.')) s=s.lastIndexOf(',')>s.lastIndexOf('.')?s.replace(/\./g,'').replace(',','.'):s.replace(/,/g,'');
  else if(s.includes(',')) s=s.replace(/\./g,'').replace(',','.');
  const n=Number(s.replace(/[^\d.-]/g,'')); return Number.isFinite(n)?n:null;
}
function dateDiffDays(a,b){
  const aa=new Date(a+'T00:00:00Z'),bb=new Date(b+'T00:00:00Z');
  return Math.round((aa-bb)/86400000);
}
let blueHist=[];
try{
  const rr=$('Obtener histórico blue ArgentinaDatos').all().map(i=>i.json);
  const flat=[];
  for(const j of rr){
    if(Array.isArray(j)) flat.push(...j);
    else if(Array.isArray(j?.data)) flat.push(...j.data);
    else if(Array.isArray(j?.body)) flat.push(...j.body);
    else if(j && j.fecha) flat.push(j);
  }
  blueHist=flat
    .map(r=>({fecha:dateKey(r.fecha),venta:numOrNull(r.venta),compra:numOrNull(r.compra)}))
    .filter(r=>r.fecha&&r.venta&&r.venta>0)
    .sort((a,b)=>a.fecha.localeCompare(b.fecha));
}catch(e){ blueHist=[]; }
function blueForDate(d){
  if(!d||!blueHist.length) return null;
  let best=null;
  for(const q of blueHist){
    if(q.fecha>d) break;
    best=q;
  }
  if(!best) return null;
  const lag=dateDiffDays(d,best.fecha);
  if(lag<0 || lag>7) return null;
  return {rate:best.venta,source:best.fecha===d?'BLUE API':'BLUE API ÚLTIMO HÁBIL',quoteDate:best.fecha};
}
const usdPurchases=activeMov.filter(r=>{
  const cur=String(r['Moneda original']||'').toUpperCase();
  const sub=String(r.Subtipo||'').toLowerCase();
  const det=String(r.Detalle||'').toLowerCase();
  const a=numOrNull(r['Monto ARS']),u=numOrNull(r['Monto original']);
  return r.Clase==='Transferencia' && cur==='USD' && a!==null && Math.abs(a)>0 && u!==null && Math.abs(u)>0 &&
    (sub.includes('compra de moneda extranjera') || det.includes('compra moneda extran') || det.includes('compra venta de dolares'));
});
function realRateForExpense(r){
  const d=dateKey(r.Fecha); const u=numOrNull(r['Monto original']);
  if(!d||u===null||Math.abs(u)<1e-9) return null;
  const same=usdPurchases.filter(x=>dateKey(x.Fecha)===d);
  if(!same.length) return null;
  const exact=same.find(x=>Math.abs(Math.abs(numOrNull(x['Monto original'])||0)-Math.abs(u))<0.01);
  if(exact){
    const ar=Math.abs(numOrNull(exact['Monto ARS'])||0),uu=Math.abs(numOrNull(exact['Monto original'])||0);
    if(ar>0&&uu>0) return {rate:ar/uu,source:'OPERACIÓN REAL',quoteDate:d};
  }
  if(same.length===1){
    const ar=Math.abs(numOrNull(same[0]['Monto ARS'])||0),uu=Math.abs(numOrNull(same[0]['Monto original'])||0);
    if(ar>0&&uu>0) return {rate:ar/uu,source:'OPERACIÓN REAL',quoteDate:d};
  }
  const ars=same.reduce((s,x)=>s+Math.abs(numOrNull(x['Monto ARS'])||0),0);
  const usd0=same.reduce((s,x)=>s+Math.abs(numOrNull(x['Monto original'])||0),0);
  return ars>0&&usd0>0 ? {rate:ars/usd0,source:'OPERACIÓN REAL PROMEDIO',quoteDate:d} : null;
}
function expenseValue(r){
  const cur=String(r['Moneda original']||'ARS').toUpperCase().trim()||'ARS';
  const arsRaw=numOrNull(r['Monto ARS']);
  const orig=numOrNull(r['Monto original']);
  if(cur!=='USD') return {equiv:arsRaw||0,arsNative:arsRaw||0,usd:0,usdEq:0,rate:null,source:null,quoteDate:null,missing:false};
  const usdAmount=orig||0;
  if(arsRaw!==null && Math.abs(arsRaw)>1e-9){
    const rate=Math.abs(usdAmount)>1e-9?Math.abs(arsRaw/usdAmount):numOrNull(r['Cotización ARS']);
    return {equiv:arsRaw,arsNative:0,usd:usdAmount,usdEq:arsRaw,rate,source:String(r['Fuente cotización']||'COTIZACIÓN REGISTRADA'),quoteDate:dateKey(r.Fecha),missing:false};
  }
  const explicit=numOrNull(r['Cotización ARS']);
  if(explicit && explicit>0){
    const eq=usdAmount*explicit;
    return {equiv:eq,arsNative:0,usd:usdAmount,usdEq:eq,rate:explicit,source:String(r['Fuente cotización']||'OPERACIÓN REAL MANUAL'),quoteDate:dateKey(r.Fecha),missing:false};
  }
  const real=realRateForExpense(r);
  if(real){
    const eq=usdAmount*real.rate;
    return {equiv:eq,arsNative:0,usd:usdAmount,usdEq:eq,...real,missing:false};
  }
  const blue=blueForDate(dateKey(r.Fecha));
  if(blue){
    const eq=usdAmount*blue.rate;
    return {equiv:eq,arsNative:0,usd:usdAmount,usdEq:eq,...blue,missing:false};
  }
  return {equiv:0,arsNative:0,usd:usdAmount,usdEq:0,rate:null,source:null,quoteDate:null,missing:true};
}
function expenseBreakdown(rows){
  const out={ars:0,usd:0,usdEq:0,total:0,missing:0,valuations:[]};
  for(const r of rows){
    const v=expenseValue(r); out.ars+=v.arsNative; out.usd+=v.usd; out.usdEq+=v.usdEq; out.total+=v.equiv; if(v.missing) out.missing++; out.valuations.push({row:r,...v});
  }
  return out;
}
function expenseRowsIn(a,b,cat=null){
  return activeMov.filter(r=>r.Clase==='Egreso'&&inRange(dateKey(r.Fecha),a,b)&&(!cat||r.Categoría===cat));
}
function fxSourceLabel(v){
  const s=String(v.source||'').toUpperCase();
  if(s.includes('OPERACIÓN REAL')) return `cot. real $${Number(v.rate||0).toLocaleString('es-AR',{maximumFractionDigits:2})}`;
  if(s.includes('BLUE')) return `blue $${Number(v.rate||0).toLocaleString('es-AR',{maximumFractionDigits:2})}${v.quoteDate?` (${v.quoteDate})`:''}`;
  if(v.rate) return `cot. $${Number(v.rate).toLocaleString('es-AR',{maximumFractionDigits:2})}`;
  return 'sin cotización';
}
function compactExpenseSummary(rows){
  const b=expenseBreakdown(rows);
  let s=money(b.total);
  if(Math.abs(b.usd)>1e-9) s+=` eq. (ARS ${money(b.ars)} + ${usd(b.usd)} → ${money(b.usdEq)})`;
  if(b.missing) s+=` ⚠️ ${b.missing} gasto${b.missing===1?'':'s'} USD sin equivalencia`;
  return s;
}

const monthNames=['','Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
const explicitPeriods=Array.isArray(p.query_periods)
  ? p.query_periods.filter(z=>z && z.period==='specific_month' && Number(z.month)>=1 && Number(z.month)<=12)
  : [];
const explicitCategories=Array.isArray(p.query_categories)
  ? [...new Set(p.query_categories.filter(Boolean))]
  : (p.query_category ? [p.query_category] : []);

function rangeForSpec(spec){
  if(!spec) return [from,to];
  if(spec.period==='specific_month'){
    const y=Number(spec.year||np.y),m=Number(spec.month||np.m);
    return [monthStart(y,m),monthEnd(y,m)];
  }
  return rangeFor(spec.period||p.query_period||'current_month');
}
function periodName(spec){
  if(spec?.period==='specific_month'){
    const y=Number(spec.year||np.y),m=Number(spec.month||np.m);
    return `${monthNames[m]} ${y}`;
  }
  return periodLabel;
}
function sumExpenseIn(a,b,cat=null){
  return expenseBreakdown(expenseRowsIn(a,b,cat)).total;
}
function sumIncomeIn(a,b){
  return activeMov
    .filter(r=>r.Clase==='Ingreso'&&inRange(dateKey(r.Fecha),a,b))
    .reduce((s,r)=>s+num(r['Monto ARS']),0);
}
function sumFinIn(a,b){
  return activeMov
    .filter(r=>r.Clase==='Resultado financiero'&&inRange(dateKey(r.Fecha),a,b))
    .reduce((s,r)=>s+num(r['Monto ARS']),0);
}

const sumClass=cl=>periodMov.filter(r=>r.Clase===cl).reduce((a,r)=>a+num(r['Monto ARS']),0);
const categorySum=cat=>expenseBreakdown(periodMov.filter(r=>r.Clase==='Egreso'&&(!cat||r.Categoría===cat))).total;
const fin=sumClass('Resultado financiero');
const gastos=categorySum(p.query_category||null);
const ingresos=sumClass('Ingreso');

let message='',details={from,to,type:p.query_type};
const periodLabel=p.query_period==='current_year'?'este año':p.query_period==='current_week'?'esta semana':p.query_period==='until_month_end'?'hasta fin de mes':p.query_period==='previous_month'?'el mes pasado':p.query_period==='specific_month'?`${from.slice(0,7)}`:p.query_period==='all'?'en todo el historial':'este mes';

switch(p.query_type){
  case 'gastos_periodo': {
    const multiPeriods=explicitPeriods.length>1;
    const multiCategories=explicitCategories.length>1;

    if(multiPeriods || multiCategories){
      const periods=explicitPeriods.length ? explicitPeriods : [{period:p.query_period||'current_month',month:p.query_month,year:p.query_year}];

      if(explicitCategories.length===1){
        const cat=explicitCategories[0];
        const lines=periods.map(spec=>{
          const [a,b]=rangeForSpec(spec);
          return `• ${periodName(spec)}: ${compactExpenseSummary(expenseRowsIn(a,b,cat))}`;
        });
        message=`💸 Gastos en ${cat}:\n${lines.join('\n')}`;
      } else if(explicitCategories.length>1){
        const blocks=periods.map(spec=>{
          const [a,b]=rangeForSpec(spec);
          const lines=explicitCategories.map(cat=>`• ${cat}: ${compactExpenseSummary(expenseRowsIn(a,b,cat))}`);
          return `${periodName(spec)}\n${lines.join('\n')}`;
        });
        message=`💸 Gastos por categoría y período:\n\n${blocks.join('\n\n')}`;
      } else {
        const lines=periods.map(spec=>{
          const [a,b]=rangeForSpec(spec);
          return `• ${periodName(spec)}: ${compactExpenseSummary(expenseRowsIn(a,b,null))}`;
        });
        message=`💸 Gastos por período:\n${lines.join('\n')}`;
      }
    } else {
      const rows0=expenseRowsIn(from,to,p.query_category||null);
      const b=expenseBreakdown(rows0);
      message=`💸 Gastos ${p.query_category?`en ${p.query_category} `:''}${periodLabel}: ${money(b.total)}`;
      if(Math.abs(b.usd)>1e-9){
        message+=`\n\n• En pesos: ${money(b.ars)}\n• En dólares: ${usd(b.usd)} → ${money(b.usdEq)}`;
        const usdVals=b.valuations.filter(v=>Math.abs(v.usd)>1e-9);
        if(usdVals.length===1 && usdVals[0].rate) message+=`\n• Cotización: ${fxSourceLabel(usdVals[0])}`;
        else if(usdVals.length>1) message+=`\n• Los USD se valuaron por fecha (cotización real cuando existe; si no, blue histórico).`;
      }
      if(b.missing) message+=`\n⚠️ ${b.missing} gasto${b.missing===1?'':'s'} USD quedó sin equivalencia por falta de cotización.`;
    }
    break;
  }

  case 'detalle_gastos_periodo': {
    const rows=periodMov
      .filter(r=>r.Clase==='Egreso'&&(!p.query_category||r.Categoría===p.query_category))
      .sort((a,b)=>String(dateKey(b.Fecha)||'').localeCompare(String(dateKey(a.Fecha)||'')));
    const total=expenseBreakdown(rows).total;
    const max=30, shown=rows.slice(0,max);
    if(!rows.length){
      message=`✅ No hay gastos ${p.query_category?`en ${p.query_category} `:''}${periodLabel}.`;
    }else{
      const lines=shown.map(r=>{
        const d=dateKey(r.Fecha)||'s/f';
        const cat=r.Categoría||'Sin categoría';
        const det=r.Detalle||r.Subtipo||'Gasto';
        const v=expenseValue(r);
        if(String(r['Moneda original']||'ARS').toUpperCase()==='USD'){
          return `${d} — ${cat} — ${det}: ${usd(v.usd)}${v.rate?` → ${money(v.usdEq)} (${fxSourceLabel(v)})`:' — ⚠️ sin cotización'}`;
        }
        return `${d} — ${cat} — ${det}: ${money(v.equiv)}`;
      });
      message=`💸 Gastos ${p.query_category?`en ${p.query_category} `:''}${periodLabel}: ${money(total)} (${rows.length})\n\n${lines.join('\n')}`;
      if(rows.length>max) message+=`\n\n…y ${rows.length-max} más.`;
    }
    break;
  }

  case 'gastos_por_categoria_periodo': {
    const by={};
    for(const r of periodMov.filter(r=>r.Clase==='Egreso')){
      const cat=r.Categoría||'Sin categoría';
      by[cat]=by[cat]||[]; by[cat].push(r);
    }
    const rows=Object.entries(by).map(([cat,rs])=>[cat,expenseBreakdown(rs)]).sort((a,b)=>b[1].total-a[1].total);
    const total=rows.reduce((a,[,v])=>a+v.total,0);
    if(!rows.length){
      message=`✅ No hay gastos ${periodLabel}.`;
    }else{
      message=`📊 Gastos por categoría ${periodLabel}: ${money(total)}\n\n`+
        rows.map(([cat,v])=>`${cat}: ${money(v.total)}${Math.abs(v.usd)>1e-9?` (incl. ${usd(v.usd)})`:''}`).join('\n');
    }
    break;
  }

  case 'ingresos_periodo': {
    if(explicitPeriods.length>1){
      const lines=explicitPeriods.map(spec=>{
        const [a,b]=rangeForSpec(spec);
        return `• ${periodName(spec)}: ${money(sumIncomeIn(a,b))}`;
      });
      message=`💰 Ingresos por período:\n${lines.join('\n')}`;
    } else {
      message=`💰 Ingresos ${periodLabel}: ${money(ingresos)}.`;
    }
    break;
  }

  case 'detalle_ingresos_periodo': {
    const rows=periodMov
      .filter(r=>r.Clase==='Ingreso')
      .sort((a,b)=>String(dateKey(b.Fecha)||'').localeCompare(String(dateKey(a.Fecha)||'')));
    const total=rows.reduce((a,r)=>a+num(r['Monto ARS']),0);
    const max=30, shown=rows.slice(0,max);
    if(!rows.length){
      message=`✅ No hay ingresos ${periodLabel}.`;
    }else{
      const lines=shown.map(r=>{
        const d=dateKey(r.Fecha)||'s/f';
        const cat=r.Categoría||'Sin categoría';
        const det=r.Detalle||r.Subtipo||'Ingreso';
        return `${d} — ${cat} — ${det}: ${money(r['Monto ARS'])}`;
      });
      message=`💰 Ingresos ${periodLabel}: ${money(total)} (${rows.length})\n\n${lines.join('\n')}`;
      if(rows.length>max) message+=`\n\n…y ${rows.length-max} más.`;
    }
    break;
  }
  case 'disponible_actual': {
    const rows=acc.filter(r=>String(r.Disponible||'').toLowerCase()==='sí' || String(r.Disponible||'').toLowerCase()==='si');
    const total=rows.reduce((a,r)=>a+num(r['Saldo actual ARS']),0);
    const parts=rows.filter(r=>num(r['Saldo actual ARS'])!==0).map(r=>`${r.Cuenta}: ${money(r['Saldo actual ARS'])}`);
    message=`💵 Disponible actual: ${money(total)}${parts.length?`\n\n${parts.join('\n')}`:''}`;
    break;
  }
  case 'invertido_actual': {
    const investments=acc.filter(r=>['FIMA','Balanz'].includes(String(r.Cuenta)));
    const fima=investments.filter(r=>r.Cuenta==='FIMA').reduce((a,r)=>a+num(r['Saldo actual ARS']),0);
    const balanz=investments.filter(r=>r.Cuenta==='Balanz').reduce((a,r)=>a+num(r['Saldo actual ARS']),0);
    const pfAct=pf.filter(r=>!['VENCIDO','CANCELADO'].includes(String(r.Estado||'').toUpperCase())).reduce((a,r)=>a+num(r['Capital ARS']),0);
    if(p.query_investment==='FIMA') message=`📈 FIMA actual: ${money(fima)}.`;
    else if(p.query_investment==='Balanz') message=`📈 Balanz actual: ${money(balanz)}.`;
    else message=`📈 Invertido actual: ${money(fima+balanz+pfAct)}\n\nFIMA: ${money(fima)}\nBalanz: ${money(balanz)}\nPlazos fijos: ${money(pfAct)}`;
    break;
  }
  case 'deuda_tarjetas': {
    const ars=cards.reduce((a,r)=>a+num(r['Saldo pendiente ARS']),0);
    const u=cards.reduce((a,r)=>a+num(r['Saldo pendiente USD']),0);
    const by={};
    for(const r of cards){
      const card=r.Tarjeta||'Tarjeta';
      by[card]=by[card]||{ars:0,usd:0};by[card].ars+=num(r['Saldo pendiente ARS']);by[card].usd+=num(r['Saldo pendiente USD']);
    }
    const lines=Object.entries(by).filter(([k,v])=>v.ars||v.usd).map(([k,v])=>`${k}: ${money(v.ars)}${v.usd?` + ${usd(v.usd)}`:''}`);
    message=`💳 Deuda pendiente de tarjetas: ${money(ars)}${u?` + ${usd(u)}`:''}${lines.length?`\n\n${lines.join('\n')}`:''}`;
    break;
  }
  case 'resultado_inversiones_periodo': {
    const rows=inv.filter(r=>inRange(dateKey(r['Periodo cierre']),from,to));
    const f=rows.filter(r=>r['Inversión']==='FIMA').reduce((a,r)=>a+num(r['Resultado financiero ARS']),0);
    const b=rows.filter(r=>r['Inversión']==='Balanz').reduce((a,r)=>a+num(r['Resultado financiero ARS']),0);
    if(p.query_investment==='FIMA') message=`📊 Resultado FIMA ${periodLabel}: ${money(f)}.`;
    else if(p.query_investment==='Balanz') message=`📊 Resultado Balanz ${periodLabel}: ${money(b)}.`;
    else message=`📊 Resultado de inversiones ${periodLabel}: ${money(f+b)}\n\nFIMA: ${money(f)}\nBalanz: ${money(b)}`;
    break;
  }
  case 'ahorro_periodo': {
    if(explicitPeriods.length>1){
      const blocks=explicitPeriods.map(spec=>{
        const [a,b]=rangeForSpec(spec);
        const ing=sumIncomeIn(a,b);
        const gas=sumExpenseIn(a,b,null);
        const movFin=sumFinIn(a,b);
        const invFin=inv.filter(r=>inRange(dateKey(r['Periodo cierre']),a,b))
          .reduce((s,r)=>s+num(r['Resultado financiero ARS']),0);
        const finTotal=movFin+invFin;
        return `${periodName(spec)}: ${money(ing-gas+finTotal)}\n  Ingresos ${money(ing)} · Gastos ${money(gas)} · Financiero ${money(finTotal)}`;
      });
      message=`🏦 Resultado/ahorro por período:\n${blocks.join('\n')}`;
    } else {
      const invFin=inv.filter(r=>inRange(dateKey(r['Periodo cierre']),from,to))
        .reduce((a,r)=>a+num(r['Resultado financiero ARS']),0);
      const finTotal=fin+invFin;
      const total=ingresos-gastos+finTotal;
      message=`🏦 Resultado/ahorro ${periodLabel}: ${money(total)}\n\nIngresos: ${money(ingresos)}\nGastos: ${money(gastos)}\nResultado financiero: ${money(finTotal)}`;
    }
    break;
  }
  case 'mes_mas_gastos': {
    const y=Number(p.query_year||np.y), months=[];
    for(let m=1;m<=12;m++){
      const a=monthStart(y,m),b=monthEnd(y,m);
      const total=expenseBreakdown(expenseRowsIn(a,b,null)).total;
      months.push({m,total});
    }
    months.sort((a,b)=>b.total-a.total);
    const best=months[0];
    message=best.total?`📊 El mes con más gastos de ${y} fue ${String(best.m).padStart(2,'0')}/${y}: ${money(best.total)}.`:`Todavía no hay gastos registrados en ${y}.`;
    break;
  }
  case 'comparar_gastos_mes_anterior': {
    const curA=monthStart(np.y,np.m),curB=monthEnd(np.y,np.m);
    const pd=new Date(Date.UTC(np.y,np.m-2,1)),py=pd.getUTCFullYear(),pm=pd.getUTCMonth()+1;
    const prevA=monthStart(py,pm),prevB=monthEnd(py,pm);
    const cats=[...new Set(activeMov.filter(r=>r.Clase==='Egreso'&&r.Categoría).map(r=>r.Categoría))];
    const diffs=cats.map(cat=>{
      const cur=expenseBreakdown(expenseRowsIn(curA,curB,cat)).total;
      const prev=expenseBreakdown(expenseRowsIn(prevA,prevB,cat)).total;
      return {cat,cur,prev,diff:cur-prev};
    }).sort((a,b)=>b.diff-a.diff);
    const curTot=diffs.reduce((a,r)=>a+r.cur,0),prevTot=diffs.reduce((a,r)=>a+r.prev,0);
    const top=diffs.filter(r=>r.diff>0).slice(0,3);
    message=`📊 Gastos este mes: ${money(curTot)}\nMes anterior: ${money(prevTot)}\nDiferencia: ${money(curTot-prevTot)}${top.length?`\n\nMayores aumentos:\n${top.map(r=>`${r.cat}: +${money(r.diff)}`).join('\n')}`:''}`;
    break;
  }
  case 'patrimonio_actual': {
    const available=acc.filter(r=>String(r.Disponible||'').toLowerCase().startsWith('s')).reduce((a,r)=>a+num(r['Saldo actual ARS']),0);
    const fima=acc.filter(r=>r.Cuenta==='FIMA').reduce((a,r)=>a+num(r['Saldo actual ARS']),0);
    const balanz=acc.filter(r=>r.Cuenta==='Balanz').reduce((a,r)=>a+num(r['Saldo actual ARS']),0);
    const pfAct=pf.filter(r=>!['VENCIDO','CANCELADO'].includes(String(r.Estado||'').toUpperCase())).reduce((a,r)=>a+num(r['Capital ARS']),0);
    const debt=cards.reduce((a,r)=>a+num(r['Saldo pendiente ARS']),0);
    message=`🏠 Patrimonio neto actual: ${money(available+fima+balanz+pfAct-debt)}\n\nDisponible: ${money(available)}\nFIMA: ${money(fima)}\nBalanz: ${money(balanz)}\nPlazos fijos: ${money(pfAct)}\nDeuda tarjetas: ${money(debt)}`;
    break;
  }
  default:
    message='Entendí que es una consulta, pero todavía no tengo una consulta determinística para esa frase. Probá con gastos, ingresos, disponible, inversiones, tarjetas, patrimonio o ahorro.';
}
return [{json:{chat_id:x.chat_id,message,query_type:p.query_type,details}}];

